import {appendCaptureWarning} from './admin-capture-warning.mjs';
import {appendPaymentStatus} from './admin-payment-status.mjs?v=2';
import {pfStatusRows} from './admin-pf-status.mjs?v=3';
import {foilFinish} from './foil-options.mjs';
import {mockupsForPfOrder,appendMockup} from './admin-mockups.mjs?v=4';
import {nextStep,orderKind,paymentLabel,dateTime} from './admin-order-state.mjs';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;if(cls)n.className=cls;return n;};
export function orderActionCard(order,checkout,shipmentMails=[],{onChanged=async()=>{}}={}){const box=el('section',null,'order-next'),[owner,step]=nextStep(order,checkout,shipmentMails);box.append(el('span',orderKind(order,checkout),'pill'),el('h3','Næste skridt · '+owner),el('p',step));const states=el('div',null,'order-state-grid');for(const [label,value] of [['Betaling',paymentLabel(checkout)],['Korrektur',order.proof?`Version ${order.proof.version} · ${order.decision?order.decision.decision==='approve'?'godkendt':'ændringer ønsket':order.proof.customer?'hos kunden':'til gennemgang'}`:'Ikke modtaget'],['Oprettet',dateTime(order.createdAt)],...pfStatusRows(order)]){const cell=el('div');cell.append(el('small',label),el('strong',value));states.append(cell);}box.append(states);
 if(order.deliveryConfirmation||order.status==='shipped'&&order.shipment?.isOrderComplete){
  const delivered=Boolean(order.deliveryConfirmation);
  if(delivered)box.append(el('p','✓ Ordre leveret · manuelt bekræftet '+dateTime(order.deliveryConfirmation.at),'pill'));
  const button=el('button',delivered?'Fortryd leveret':'Bekræft leveret'),message=el('p',null,'muted');button.type='button';message.setAttribute('role','status');
  button.onclick=async()=>{
   const number=order.pfOrderNumber||order.purchaseOrderNumber;
   if(!window.confirm(delivered?'Fjern leveringsbekræftelsen for ordre '+number+'? Ordren vises igen under Leveringer.':'Bekræft, at du har kontrolleret, at hele ordre '+number+' er leveret.'))return;
   button.disabled=true;
   try{
    const response=await fetch('/api/pf-orders/'+encodeURIComponent(order.id)+'/delivery-confirmation',{method:delivered?'DELETE':'POST',credentials:'same-origin',headers:{'X-Smerch-Admin':'1'}});
    if(!response.ok){const problem=await response.json();throw Error(problem.error||'Leveringsstatus kunne ikke opdateres.');}
    await onChanged();
   }catch(error){message.textContent=error.message;button.disabled=false;}
  };
  box.append(button,message);
 }
 appendPaymentStatus(box,checkout,{onUpdate:async()=>{const cell=states.children[0]?.querySelector('strong');if(cell)cell.textContent=paymentLabel(checkout);const [owner,step]=nextStep(order,checkout,shipmentMails);box.querySelector('h3').textContent='Næste skridt · '+owner;box.children[2].textContent=step;box.querySelector('.order-problems')?.remove();box.querySelector('.capture-warning')?.remove();appendCaptureWarning(box,checkout);appendProblems();await onChanged();}});function appendProblems(){const problems=[];if(['needs_attention','needs_reconciliation'].includes(order.status))problems.push(order.pfStatusInformation||'Ordren kræver afklaring med PF.');if(checkout&&['authorization_expired','capture_reconciliation','payment_failed'].includes(checkout.status))problems.push(paymentLabel(checkout));if(problems.length){const issues=el('div',null,'order-problems');issues.setAttribute('role','status');for(const problem of problems)issues.append(el('p',problem));box.append(issues);}}appendCaptureWarning(box,checkout);appendProblems();return box;}
export function orderProductCards(order,checkout){const box=el('section',null,'order-products');box.append(el('h2','Det har kunden bestilt'));const refs=mockupsForPfOrder(checkout,order);const group=Number.isInteger(order.checkoutGroupIndex)?order.checkoutGroupIndex:checkout?.pfOrderIds?.indexOf(order.id),indexes=checkout?.fulfillmentGroups?.[group];for(const [i,line] of (order.lines||[]).entries()){const card=el('article',null,'order-product-card'),media=el('div',null,'order-product-media'),info=el('div');const sourceIndex=indexes?.[i]??i;const images=refs.filter(ref=>ref.lineIndex===sourceIndex);for(const image of images)appendMockup(media,image);if(!images.length)media.append(el('p',line.decorations?.length?'Mockup mangler':'Uden tryk','mockup-empty'));info.append(el('h3',`${line.quantity} stk. · ${checkout?.productNames?.[line.productId]||line.productName||line.productId}`),el('p',`Varenummer ${line.sku}`,'muted'));if(line.color||line.size)info.append(el('p',[line.color,line.size].filter(Boolean).join(' · ')));for(const d of line.decorations||[]){const design=el('section',null,'order-decoration');design.append(el('h4',[d.position,d.method,d.foilFinish?foilFinish(d.foilFinish)?.label:null].filter(Boolean).join(' · ')),el('p',`${d.width} × ${d.height} mm · ${d.colors} farve${d.colors===1?'':'r'}`),el('strong',(d.pmsColors||[]).join(' · ')||'Farvekode ikke registreret'));if(d.text)design.append(el('p','Tekst: '+d.text));for(const [a,art] of (d.artworks||[]).entries()){const link=el('a','Originalfil: '+art.logo.name);link.href=order.checkoutId?`/api/admin/checkouts/${order.checkoutId}/artwork/${art.logo.id}`:d.files?.raw?.[a]||'#';design.append(link);}info.append(design);}card.append(media,info);box.append(card);}box.append(el('p','Designmockup viser bestillingen. PF’s produktionskorrektur godkendes særskilt.','muted'));return box;}
